"% Define the loop transfer function L(s) = 9 / (s^3 + 5s^2 + 6s)
num = [9.0];
den = [1.0, 5.0, 6.0, 0.0];
L = tf(num, den);

% Compute classical stability margins using Control System Toolbox margin()
%   gm  : gain margin (linear)
%   pm  : phase margin (degrees)
%   wcg : gain crossover frequency (|L(jw)| = 1, i.e. 0 dB)
%   wcp : phase crossover frequency (angle(L(jw)) = -180 deg)
[gm, pm, wcg, wcp] = margin(L);

% Convert gain margin to dB
gm_db = 20 * log10(gm);

% Package results into a struct with the required key names
result = struct();
result.gm_db = gm_db;
result.pm_deg = pm;
result.w_gc  = wcg;
result.w_pc  = wcp;

% Serialize to JSON and write to result.json in current working directory
json_text = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_text);
fclose(fid);"
